import numpy as np


def safe_normalise(E, eps=1e-12):
    E = np.asarray(E, dtype=float)
    n = np.sqrt((E ** 2).sum(axis=1, keepdims=True))
    return np.where(n > eps, E / np.where(n > eps, n, 1.0), E)


def cosine_matrix(E):
    N = safe_normalise(E)
    return N.T @ N
